export function getRegistryIndex() {
  return Object.values(components).map((component) => ({
    name: component.name,
    type: "registry:ui" as const,
    dependencies: component.dependencies,
    registryDependencies: [],
    files: [{ path: `components/ui/${component.slug}.tsx`, type: "registry:ui" as const }],
  }));
}

export function getRegistryComponent(slug: string) {
  const component = components[slug];
  if (!component) return null;
  return {
    name: component.name,
    type: "registry:ui" as const,
    dependencies: component.dependencies,
    registryDependencies: [],
    files: [{ path: `components/ui/${component.slug}.tsx`, content: component.code, type: "registry:ui" as const }],
  };
}
